"""Render honest debug pictures and summarize every case, including failures."""
import json
from pathlib import Path
from PIL import Image, ImageDraw

BASE = Path(__file__).resolve().parent


def picture(sample, row, name):
    bb = sample['box']
    scale, pad = 2, 22
    w, h = round((bb[2] - bb[0]) * scale) + 2 * pad, round((bb[3] - bb[1]) * scale) + 2 * pad + 24
    im = Image.new('RGB', (w, h), 'white')
    draw = ImageDraw.Draw(im)

    def rect(b, color):
        if b is None:
            return
        x1, y1, x2, y2 = b
        draw.rectangle([pad + (x1 - bb[0]) * scale, pad + (bb[3] - y2) * scale + 24,
                        pad + (x2 - bb[0]) * scale, pad + (bb[3] - y1) * scale + 24], outline=color)

    rect(bb, '#111111')
    for slot in sample['slots']:
        y = pad + (bb[3] - slot['baseline']) * scale + 24
        draw.line([pad, y, w - pad, y], fill='#dddddd')
    if row is None:
        for g in sample['glyphs']:
            if g.get('source') and g['text'].strip():
                rect(g['ink'], '#777777')
        title = 'BEFORE: original PDFium/source boxes'
    else:
        for g in row['glyphs']:
            if g['text'].strip():
                rect(g['ink'], '#1672b7' if g['source_index'] is not None else '#d66016')
        title = f"AFTER DEBUG {row['edit']}: fits={row['fits']}; {row['after_lines']} lines"
    draw.text((8, 5), title, fill='black')
    im.save(BASE / 'artifacts' / name, optimize=True)


def f(v):
    return 'n/a' if v is None else f'{v:.6f}'


def report():
    samples = json.loads((BASE / 'tmp/input.json').read_text())
    result = json.loads((BASE / 'tmp/layouts.json').read_text())
    rows = result['rows']
    edits = [r for r in rows if r['edit'] != 'identity']
    dependencies = json.loads((BASE / 'tmp/cargo-metadata.json').read_text())['packages']
    # Separate redistributable summaries from ignored embedded font dumps.
    inventory = []
    for s in samples:
        original = [g for g in s['glyphs'] if g.get('source')]
        drifts = [max(abs(g['x'] - g['nativeOrigin'][0]), abs(g['y'] - g['nativeOrigin'][1]))
                  for g in original if g['nativeOrigin'] is not None]
        fonts = []
        for key in sorted({g['font'] for g in original}):
            font = s['fonts'][key]
            fonts.append({k: font[k] for k in ['name', 'object', 'programKind', 'byteCount', 'verified', 'metricSource', 'type1CodeFailures']})
            if 'type1MetricFailure' in font:
                fonts[-1]['type1MetricFailure'] = font['type1MetricFailure']
        inventory.append(dict(id=s['id'], page=s['page'], box=s['box'], slots=s['slots'],
            hash=s['hash'], url=s['url'], licence=s['licence'], fonts=fonts,
            source_glyphs=len(original), inferred_spaces=s['inferred_spaces'],
            inferred_space_rules={kind: sum(g.get('inference') == kind for g in s['glyphs'])
                                  for kind in ['gap>0.12*size', 'soft-join-0.25em']},
            column_clip=s['column_clip'], stroke_geometry_only_ops=s['stroke_geometry_only_ops'],
            unmatched_native=sum(g['nativeOrigin'] is None for g in original),
            unproven_unicode=sum(not g['unicodeProven'] for g in original),
            native_origin_max=max(drifts, default=0), native_origin_mean=sum(drifts) / max(1, len(drifts)),
            original=s['original'], source_lines=s['source_lines']))
    (BASE / 'artifacts/samples.json').write_text(json.dumps(inventory, ensure_ascii=False, indent=2) + '\n')
    notices = '\n'.join(f"| {p['name']} | {p['version']} | {p['license']} |" for p in sorted(dependencies, key=lambda p: p['name']))
    (BASE / 'DEPENDENCIES.md').write_text('# Prototype dependency licenses\n\nGenerated by `bash research/reflow-proto/run.sh`; not a shipping dependency approval.\n\n| Crate | Version | Declared SPDX license |\n|---|---|---|\n' + notices + '\n')
    text = ['# Fixed-box reflow research results', '',
        'Generated by `bash research/reflow-proto/run.sh` on the pinned corpus. This is **layout/debug evidence, not an edited-PDF round trip, production acceptance rate, O0 run, or RegionProof**.', '',
        f"Engine: {result['engine']}. Six body paragraphs, 24 edits plus six identity controls. "
        f"Geometric fit: **{sum(r['fits'] for r in edits)}/24 edits**; "
        f"**{sum(not r['fits'] for r in edits)}/24 do not fit**. These counts do not imply safe exports. "
        f"Linux x86_64 stripped release executable: **{result['release_binary_bytes']:,} bytes** "
        '(includes JSON CLI, shaping and diagnostic font parser; not incremental Tauri/Android size).', '',
        '## Method and definitions', '',
        '- Bounds and baseline slots were frozen from real source placements/ink **before** edits. No blank slots, box growth, font scaling or full justification. First-line/hanging capacities are retained per slot, matching the new §4.5 indent unit. This manually selected geometry is still not a RegionProof.',
        '- Research extraction neutralizes Tr 1/2 only for numeric advances because the shared production walker now refuses stroked text. Counts are recorded per sample as `stroke_geometry_only_ops`. Paint semantics and stroke ink are not certified; these samples cannot acquire a RegionProof from this runner.',
        '- Chinese inserts/expansions use **fixed token index 8** (zero-based boundary after eight input tokens), which can split a word; this is not a linguistic phrase-boundary detector. Inserts add `在实际应用中`; exact joined snippets are quoted below. English inserts add `carefully ` after the first source/inferred space. Deletes remove `人工智能` or a first-line word. The table reports actual Unicode-scalar length change; +10/+30 use additional same-script prose, rounded to nearby English word boundaries.',
        '- Unchanged source codes bypass shaping. Rust recalculates advances from supplied widths, Tf/Tc/Tw/Tz and the transformed basis; measured boundary gaps are retained when original neighbours remain together. For Type1 only, TS parses the program with the production parser, checks raw fractional widths against the PDF dictionary in character space (tolerance 1), then supplies the native whole-unit program advance. Original `pdfWidth1000` and fractional `programWidth1000` remain separate in the extracted input. **The near-zero adapter advance error is not an independent oracle.** Source offsets and native PDFium origins are recorded separately.',
        '- Baseline drift compares output lines in retained source slots with original baselines; it is zero by construction on this fixed grid. It says nothing about x drift, moved glyph correctness or spacing between ink envelopes. Overflow lines are counted but have **null origins**: no unauthorised baseline is invented.',
        '- Verified embedded TrueType code→GID mappings remain usable even when a subset Unicode cmap cannot shape the text. New source-coded clusters use `/W` or `/Widths`; unavailable/new glyphs use Noto SC or the existing Liberation Serif TTF, with HarfRust shaping. Type1 parsing stays entirely in production TypeScript; Rust still parses no Type1. Research source width measurement does not authorize new Type1 glyph reuse or change production dictionary-width authority. A fallback advance is a program metric in this spike; an emitted subset dictionary/permission proof is still required before production use.',
        '- English **inferred gap spaces** use the heuristic `gap > 0.12 * size`; inferred soft joins add `0.25 * size` (0.25 em) when the source line does not end in `-`. These spaces are not manually reviewed/reconstructed. They have no source/code/GID/native-origin/Unicode proof; only style and diagnostic geometry remain. Literal source hyphens are retained without dehyphenation. Unknown Unicode uses native labels where available and remains unproven. No inferred whitespace, unknown font mapping, interleaved operators, multi-BT content, or geometry-only manual region is certified safe by this runner.',
        '- `extract.ts` applies a manual glyph-origin x filter: it drops `arxiv-2611.17030` glyphs with `x > 300 pt` and `arxiv-2611.17053` glyphs with `x > 310 pt` before grouping left-column lines. These are fixed research column clips, not a proven column detector or PDF clip; kept glyph ink can extend beyond the threshold. Excluded glyph counts are recorded in `samples.json`.',
        '- Every edit note carries the sample identity-control native source x maximum. The legacy `native_stationary_x_max` field is labelled by `native_comparison_scope`: inserts/expansions compare only the unmoved prefix (`prefix-only`); identity/deletion compare remaining source glyphs. A small prefix figure does not replace the full identity-control failure.',
        '- The wider UAX14 candidate set is diagnostic; production still intersects the §4.6 Latin-space/plain-Han whitelist. The prototype does not perform the TS spacing/suffix-shift cascade, validate all obstacles/semantic scopes, prevent every TJ-kern split, compile Tj/TJ or validate rejoin Tlm. Ordinary deletion preserves all remaining source glyph positions and intentional gaps.', '',
        '## Sample provenance and source/native checks', '',
        'Pages are **1-based**. Exact boxes, every baseline/slot, SHA-256, original paragraph text/line fragments, source URLs and font metadata are in [samples.json](artifacts/samples.json). Code/item addresses and font dumps regenerate under ignored `tmp/`. Source corpus attribution and licensing are inherited from `scripts/pdf-corpus/manifest.json`; modifications/debug visualizations are by Shiori. No corpus PDFs or font programs are committed.', '',
        '| Corpus ID / page | Original lines | Fixed box (left,bottom,right,top) pt | Source fonts / extraction | Inferred spaces; unproven Unicode; native unmatched | Native source origin max / mean pt |',
        '|---|---:|---|---|---|---|']
    for s in inventory:
        names = '; '.join(f"{p['name']} ({p['programKind']}, {p['byteCount']} B, {p['verified']})" for p in s['fonts'])
        text.append(f"| {s['id']} / {s['page']} | {len(s['slots'])} | " + ', '.join(f'{v:.3f}' for v in s['box'])
                    + f" | {names} | {s['inferred_spaces']}; {s['unproven_unicode']}; {s['unmatched_native']} | {f(s['native_origin_max'])} / {f(s['native_origin_mean'])} |")
    identity = next(r for r in rows if r['id'] == 'arxiv-2611.17053' and r['edit'] == 'identity')
    text += ['', f"**Independent Type1 identity control:** arxiv-2611.17053 max native x drift is **{identity['native_identity_control_x_max']:.9f} pt** (target ≤0.005 pt; original 0.261620 pt). The production TS parser supplies program widths, checked before any quantization. A separate hand-built A/B/C fractional-width PDF confirms the pinned native reader consumes whole-unit advances: `bun research/reflow-proto/type1NativeProbe.ts`; inputs/report are under `test-artifacts/reflow-type1-native/`. This is reader-specific research measurement, not a change to production PDF metrics or glyph eligibility. Unsupported programs and individual width conflicts remain recorded. Missing native matches (including spaces/ligature extraction) are counted, never assumed passes. Chinese unknown labels and font-state changes likewise prevent any claim that these are production-eligible paragraphs.", '',
        '## Fixed-index Chinese insertion snippets', '',
        'These are exact joined snippets from fixed token index 8, not edits after a detected opening phrase. The quoted suffix is truncated only for display:', '',
        '| Sample | Joined snippet (inserted text included) |', '|---|---|']
    for s in samples:
        if s['id'].startswith('zh'):
            prefix = ''.join(g['text'] for g in s['glyphs'][:8])
            suffix = ''.join(g['text'] for g in s['glyphs'][8:16])
            text.append(f"| {s['id']} | `{prefix}在实际应用中{suffix}…` |")
    text += ['', '## Row-level Stage-5 limiters', '',
        '- All three Chinese paragraphs have a first-line indent of about 20 pt (106.68 versus about 86.64). arxiv-2611.17030 and .17053 are indented too. The §4.5 indent unit now models those per-line capacities; their manual boxes still lack complete source/scene/semantic proofs even when diagnostic geometry fits.',
        '- **education / insert:** diagnostic wrapping breaks after `·` and `。`, outside the §4.6 Latin-space/plain-Han whitelist. Its geometric fit is not a supported Stage-5 wrap.',
        '- **arxiv-2611.17052 / insert:** wrapping uses inferred gap spaces, so a source-code/whitespace proof is absent. Liberation advances are program metrics in this spike, not verified emitted fallback dictionary widths.',
        '- **arxiv-2611.17030 / delete:** this 15-line result is among the 10 geometric fits but exceeds the eight-line Stage-5 cap; identity also exceeds it. The count does not imply production eligibility.', '',
        '## All sample × edit metrics', '',
        '`Fits` means advance/ink envelopes fit the fixed geometry in this diagnostic algorithm. It does **not** mean production eligible. “Noto”/“Liberation” below is **replacement** fallback; unchanged text keeps its source font/code/metrics. Controls and deletions add no new font.', '',
        '| Sample | Edit (actual Δ length) | Fits | Lines before → required | Max baseline drift pt | Unchanged advance max / mean pt vs PDF widths | Replacement font used | Notes / failure |',
        '|---|---|---|---|---:|---|---|---|']
    for r in rows:
        chinese = r['id'].startswith('zh')
        font = 'no new glyphs' if r['edit'] in ('identity', 'delete') else 'embedded TT'
        if r['replacement_fallback_glyphs']:
            font = ('embedded TT + Noto SC' if chinese else 'Liberation Serif (Type1 unsupported)') + f"; {r['replacement_fallback_glyphs']} fallback glyphs"
        notes = '; '.join(r['notes']) or 'geometry only; source/proof limitations above'
        text.append(f"| {r['id']} | {r['edit']} ({r['length_change_percent']:+.1f}%) | {'yes' if r['fits'] else 'no'} | "
                    f"{r['before_lines']} → {r['after_lines']} | {f(r['baseline_drift_max'])} | "
                    f"{f(r['pdf_advance_max'])} / {f(r['pdf_advance_mean'])} ({r['unchanged_count']} glyphs) | {font} | {notes} |")
    text += ['', '## Raw program metrics and prohibition checks', '',
        '| Sample (identity) | Raw hmtx vs PDF width max / mean pt |', '|---|---|']
    for r in rows:
        if r['edit'] == 'identity':
            text.append(f"| {r['id']} | {f(r['raw_font_advance_max'])} / {f(r['raw_font_advance_mean'])} |")
    text += ['', 'Raw hmtx is n/a for Type1; its widths were parsed in TypeScript, never Rust. Embedded TT rows agree for their mapped source GIDs; the independent native origin check above remains necessary.', '',
        f"Across all candidate corpus layouts, **{sum(r['prohibition_breaks'] for r in rows)}** breaks before configured closing punctuation/after opening punctuation were observed. "
        'The small diagnostic strings below inspect UAX14 candidates as well; this is not a complete locale kinsoku conformance suite:', '']
    for p in result['kinsoku']:
        text.append(f"- `{p['text']}`: UAX14 candidates violating the configured prohibition filter: `{p['uax_prohibited_candidates']}`.")
        for wrap in p['wraps']:
            text.append(f"  - Width {wrap['unit_width']} units: `{' / '.join(wrap['visual_lines'])}`; unsupported required break: `{wrap['unsupported']}`.")
    text += ['', '## Debug image pairs', '',
        '**These PNGs contain glyph/ink boxes, not rendered edited text or a saved PDF.** Gray source boxes are native PDFium where matched (descriptor estimates for unmatched glyphs); blue is reflowed unchanged text, orange is replacement ink. Black is the predeclared box; gray horizontal lines are the original baseline slots. Overflow glyphs with null origins are absent from the picture and remain in ignored `tmp/layouts.json`; [metrics.json](artifacts/metrics.json) retains every summary/visual line. Native glyph pixels/outside-mask pixels, qpdf and Poppler round trips have not been tested.', '']
    for corpus_id, edit in [('zh-hans-education', 'insert'), ('zh-hans-ethics', '+10%'), ('arxiv-2611.17052', 'insert')]:
        s = next(s for s in samples if s['id'] == corpus_id)
        r = next(r for r in rows if r['id'] == corpus_id and r['edit'] == edit)
        before, after = corpus_id + '-before.png', corpus_id + '-after.png'
        picture(s, None, before); picture(s, r, after)
        text.append(f"- {corpus_id}, {edit}: [before](artifacts/{before}), [after debug](artifacts/{after}).")
    text += ['', '## Decision and remaining gates', '',
        'The measured-cluster design preserves dictionary advances while allowing a small exact slot breaker. General paragraph typography is unnecessary for this scope; the source/font/TJ proof is the hard part. The actual +30% cases overflow, and some short inserts fit, without changing the box. This supports the interface choice, not a forecast.', '',
        'Still required before production: validated RegionProof/obstacles/semantics/single-BT ownership; source whitespace/Unicode round trips; native-width disagreement resolution; complete mandatory break/kern guards; fallback permission/subset dictionary metrics; Type1 F5; actual TS↔Rust codec/platform builds; R8 Tj/TJ surgery and rejoin; O1b native before/after PDFs and raster/extraction gates. Nothing in this spike changes the default-off policy.', '',
        'Verification is the complete six-paragraph/30-case run plus independent source/native comparisons, Cargo fmt and clippy. See [README](README.md) for the single regeneration command, dependencies, failure history and exact artifact semantics.', '']
    (BASE / 'RESULTS.md').write_text('\n'.join(text))
    print(f"Generated RESULTS.md, samples.json, dependency licenses and six debug PNGs; {sum(r['fits'] for r in edits)}/24 geometric fits")


if __name__ == '__main__':
    report()
